mapper.select:
SELECT id
FROM vi_order
WHERE order_no=#{orderNo}

mapper.sql:
WHERE o.fulfillment_status IN ('SCHEDULED','PENDING_DISPATCH','DISPATCHING','MANUAL_DISPATCH')

AND o.order_no=#{q.orderNo}
AND o.station_id=#{q.stationId}
AND o.service_company_id=#{q.serviceCompanyId}
AND o.fulfillment_status=#{q.status}

mapper.select:
SELECT o.*
FROM vi_order o 
ORDER BY o.pickup_starts_at,o.id
LIMIT #{q.pageSize}
OFFSET #{q.offset}

mapper.sql:
WHERE 1=1 
AND i.driver_id=#{driver}
AND i.driver_id=#{q.driverId}
AND o.order_no=#{q.orderNo}

    AND (CASE WHEN i.status='WAIT_RESPONSE' AND i.expires_at<=#{now,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler}
        THEN 'EXPIRED' ELSE i.status END)=#{q.status}

mapper.select:
SELECT i.*
FROM vi_dispatch_invite i
JOIN vi_order o ON o.id=i.order_id
 ORDER BY i.id DESC
LIMIT #{q.pageSize}
OFFSET #{q.offset}

SELECT *
FROM vi_dispatch_invite
WHERE id=#{id}

SELECT (
    EXISTS(
        SELECT 1
        FROM vi_driver_assignment
        WHERE driver_id=#{driver}
            AND ended_at IS NULL
    )
    OR EXISTS(
        SELECT 1
        FROM vi_dispatch_invite
        WHERE driver_id=#{driver}
            AND status='WAIT_RESPONSE'
            AND id<>#{ownInvite}
    )
)

mapper.update:
UPDATE vi_dispatch_invite
SET reason_cipher=#{cipher}
WHERE id=#{id} AND version=0 AND status='WAIT_RESPONSE' AND reason_cipher IS NULL

mapper.select:
SELECT COALESCE(MAX(run_no),0)+1
FROM vi_dispatch_batch
WHERE order_id=#{orderId}

SELECT COUNT(*)
FROM vi_dispatch_invite
WHERE batch_id=#{batch} AND driver_id=#{driver}

mapper.delete:
DELETE
FROM vi_driver_occupancy
WHERE driver_id=#{driver} AND order_id=#{order} AND holder_type='INVITE' AND holder_id=#{invite}

mapper.select:
SELECT id
FROM vi_driver_assignment
WHERE invite_id=#{invite}

mapper.update:
UPDATE vi_order
SET fulfillment_status=#{state},active_assignment_id=#{assignment},version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE id=#{row.id} AND version=#{row.version}
